def build_hash(s={{s}}, mod={{mod}}, base={{base}}):
    n = len(s)
    h = [0]*(n+1); pw = [1]*(n+1)
    for i in range(n):
        h[i+1] = (h[i]*base + ord(s[i])) % mod
        pw[i+1] = pw[i]*base % mod
    return h, pw

def get_hash(h, pw, l, r, mod):
    return (h[r+1] - h[l]*pw[r-l+1]) % mod
